package com.proxy.gateway

import java.net.{ServerSocket, Socket}
import java.io.{BufferedReader, InputStreamReader, OutputStream}
import java.util.concurrent.{ConcurrentHashMap, Executors}
import scala.collection.mutable

object FeatureFlags {
  private val flags = new ConcurrentHashMap[String, Boolean]()
  flags.put("sanitize_html", true)
  flags.put("debug_mode", false)
  flags.put("legacy_compat", true)
  flags.put("strict_encoding", true)

  def isEnabled(flag: String): Boolean = flags.getOrDefault(flag, false)
  def setFlag(flag: String, value: Boolean): Unit = flags.put(flag, value)
}

object ContentTransformer {
  private val DANGEROUS_TAGS = Set("script", "iframe", "object", "embed", "svg")
  private val DANGEROUS_ATTRS = Set("onerror", "onload", "onclick", "onmouseover")

  def sanitizeHtml(content: String): String = {
    var result = content
    for (tag <- DANGEROUS_TAGS) {
      result = result.replaceAll(s"(?i)<$tag", s"&lt;$tag")
      result = result.replaceAll(s"(?i)</$tag>", s"&lt;/$tag&gt;")
    }
    for (attr <- DANGEROUS_ATTRS) {
      result = result.replaceAll(s"(?i)$attr\\s*=", s"data-blocked-$attr=")
    }
    result
  }

  def encodeForContext(content: String, context: String): String = {
    context match {
      case "html_body" => htmlEncode(content)
      case "html_attr" => attrEncode(content)
      case "javascript" => jsEncode(content)
      case "url_param" => urlEncode(content)
      case _ => content
    }
  }

  private def htmlEncode(s: String): String =
    s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
      .replace("\"", "&quot;").replace("'", "&#x27;")

  private def attrEncode(s: String): String =
    s.flatMap(c => if (c.isLetterOrDigit) s"$c" else s"&#x${c.toInt.toHexString};")

  private def jsEncode(s: String): String =
    s.flatMap(c => if (c.isLetterOrDigit) s"$c" else s"\\u${f"${c.toInt}%04x"}")

  private def urlEncode(s: String): String =
    java.net.URLEncoder.encode(s, "UTF-8")
}

object ErrorPageRenderer {
  def renderError(statusCode: Int, path: String, queryParams: Map[String, String]): String = {
    val sanitizedPath = if (FeatureFlags.isEnabled("sanitize_html")) {
      ContentTransformer.sanitizeHtml(path)
    } else {
      path
    }

    val debugInfo = if (FeatureFlags.isEnabled("debug_mode")) {
      s"""<div class="debug">Request path: $sanitizedPath</div>"""
    } else ""

    val redirectScript = buildRedirectScript(queryParams)

    s"""<!DOCTYPE html>
       |<html><head><title>Error $statusCode</title></head>
       |<body>
       |<h1>Error $statusCode</h1>
       |<p>The requested resource was not found.</p>
       |$debugInfo
       |$redirectScript
       |</body></html>""".stripMargin
  }

  private def buildRedirectScript(params: Map[String, String]): String = {
    params.get("redirect_url") match {
      case Some(url) =>
        val encodedUrl = if (FeatureFlags.isEnabled("strict_encoding")) {
          ContentTransformer.encodeForContext(url, resolveEncodingContext(url))
        } else {
          url
        }
        s"""<script>setTimeout(function(){window.location="$encodedUrl";},3000);</script>"""
      case None => ""
    }
  }

  private def resolveEncodingContext(url: String): String = {
    if (FeatureFlags.isEnabled("legacy_compat")) {
      // Legacy mode: treat URLs embedded in script tags as url_param context
      // since they'll be used in window.location assignment
      "url_param"
    } else {
      "javascript"
    }
  }
}

class ProxyHandler(clientSocket: Socket) extends Runnable {
  override def run(): Unit = {
    try {
      val reader = new BufferedReader(new InputStreamReader(clientSocket.getInputStream))
      val output = clientSocket.getOutputStream
      val requestLine = reader.readLine()
      if (requestLine == null) return

      val parts = requestLine.split(" ")
      if (parts.length < 3) return

      val method = parts(0)
      val fullPath = parts(1)
      val (path, queryString) = fullPath.split("\\?", 2) match {
        case Array(p, q) => (p, q)
        case Array(p) => (p, "")
      }

      val queryParams = parseQueryString(queryString)

      // Check for admin flag control endpoint
      if (path == "/admin/flags" && method == "POST") {
        handleFlagUpdate(reader, output)
        return
      }

      // Simulate upstream being unavailable for demo
      val errorPage = ErrorPageRenderer.renderError(404, path, queryParams)
      sendResponse(output, 404, errorPage)
    } catch {
      case _: Exception => ()
    } finally {
      clientSocket.close()
    }
  }

  private def parseQueryString(qs: String): Map[String, String] = {
    if (qs.isEmpty) return Map.empty
    qs.split("&").flatMap { param =>
      param.split("=", 2) match {
        case Array(k, v) => Some(java.net.URLDecoder.decode(k, "UTF-8") ->
          java.net.URLDecoder.decode(v, "UTF-8"))
        case _ => None
      }
    }.toMap
  }

  private def handleFlagUpdate(reader: BufferedReader, output: OutputStream): Unit = {
    // Read headers to get content length
    var contentLength = 0
    var line = reader.readLine()
    while (line != null && line.nonEmpty) {
      if (line.toLowerCase.startsWith("content-length:")) {
        contentLength = line.split(":", 2)(1).trim.toInt
      }
      line = reader.readLine()
    }
    val body = new Array[Char](contentLength)
    reader.read(body, 0, contentLength)
    val bodyStr = new String(body)
    // Parse simple key=value&enabled=true format
    val params = bodyStr.split("&").flatMap { p =>
      p.split("=", 2) match {
        case Array(k, v) => Some(k -> v)
        case _ => None
      }
    }.toMap
    params.get("flag").foreach { flag =>
      val enabled = params.getOrElse("enabled", "true").toBoolean
      FeatureFlags.setFlag(flag, enabled)
    }
    sendResponse(output, 200, "OK")
  }

  private def sendResponse(output: OutputStream, status: Int, body: String): Unit = {
    val statusText = if (status == 200) "OK" else "Not Found"
    val response = s"HTTP/1.1 $status $statusText\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: ${body.getBytes("UTF-8").length}\r\nX-Content-Type-Options: nosniff\r\n\r\n$body"
    output.write(response.getBytes("UTF-8"))
    output.flush()
  }
}

object ProxyServer extends App {
  val port = 8080
  val server = new ServerSocket(port)
  val pool = Executors.newFixedThreadPool(10)
  println(s"Proxy listening on port $port")
  while (true) {
    val client = server.accept()
    pool.execute(new ProxyHandler(client))
  }
}
